/**
 * Site-wide image paths used by metadata and schema.
 *
 * DEFAULT_OG_IMAGE is the 1200x630 fallback social card (generated by
 * scripts/gen-og-image.js from the wordmark on the dark brand background).
 * The filename carries a date so a regenerated card is a NEW URL — social
 * platforms and crawlers cache og:image aggressively, so never reuse a
 * previous filename for changed artwork.
 *
 * Both layout.tsx (site-wide default) and the homepage metadata use this
 * constant, so the card can only ever be changed in one place.
 */
export const DEFAULT_OG_IMAGE = {
  url: '/og/jupiterbd-default-20261010.png',
  width: 1200,
  height: 630,
  alt: 'Jupiter BD — gadget prices, specs and reviews in Bangladesh',
} as const;

/** Brand wordmark (the header logo asset) — used by Organization schema. */
export const LOGO_IMAGE_URL = '/logo/logo.png';
